code:
def solve(coins, amount):
    # Dynamic programming: dp[i] = min coins to make amount i
    # Initialize dp with a large sentinel value.
    INF = amount + 1  # larger than any possible number of coins
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        best = INF
        for c in coins:
            if c <= a:
                cand = dp[a - c] + 1
                if cand < best:
                    best = cand
        dp[a] = best
    return dp[amount] if dp[amount] != INF else -1

