def solve(matrix):
    """Return elements of the rectangular matrix in clockwise spiral order.
    Handles empty matrix and empty inner rows.
    """
    if not matrix or not any(matrix):
        return []
    # Determine dimensions; assume rectangular but guard against empty rows.
    rows = len(matrix)
    cols = len(matrix[0]) if matrix[0] else 0
    if cols == 0:
        return []
    top, bottom = 0, rows - 1
    left, right = 0, cols - 1
    result = []
    while top <= bottom and left <= right:
        for c in range(left, right + 1):
            result.append(matrix[top][c])
        top += 1
        for r in range(top, bottom + 1):
            result.append(matrix[r][right])
        right -= 1
        if top <= bottom:
            for c in range(right, left - 1, -1):
                result.append(matrix[bottom][c])
            bottom -= 1
        if left <= right:
            for r in range(bottom, top - 1, -1):
                result.append(matrix[r][left])
            left += 1
    return result

