def solve(s: str) -> str:
    n = len(s)
    if n == 0:
        return ''
    best_start = 0
    best_len = 1
    def expand(l, r):
        while l >= 0 and r < n and s[l] == s[r]:
            l -= 1
            r += 1
        return l+1, r-1  # inclusive indices of palindrome
    for i in range(n):
        # odd length center i
        l, r = expand(i, i)
        cur_len = r - l + 1
        if cur_len > best_len or (cur_len == best_len and l < best_start):
            best_start, best_len = l, cur_len
        # even length center i,i+1
        if i+1 < n:
            l, r = expand(i, i+1)
            cur_len = r - l + 1
            if cur_len > best_len or (cur_len == best_len and l < best_start):
                best_start, best_len = l, cur_len
    return s[best_start:best_start+best_len]

