def _pi(x):
    """Exact prime counting function pi(x) for x >= 0 (Meissel-Lehmer style)."""
    if x < 2:
        return 0
    r = int(x ** 0.5)
    while r * r > x:
        r -= 1
    while (r + 1) * (r + 1) <= x:
        r += 1
    # base primes up to r via sieve
    if r < 2:
        return x if x >= 2 else 0  # x < 4 here... handled below anyway
    sieve = bytearray([1]) * (r + 1)
    sieve[0:2] = b'\x00\x00'
    i = 2
    while i * i <= r:
        if sieve[i]:
            sieve[i * i::i] = bytearray(len(range(i * i, r + 1, i)))
        i += 1
    primes = [i for i in range(2, r + 1) if sieve[i]]

    def phi(m, k):
        # count of numbers <= m not divisible by first k primes (iterative for speed)
        while k > 0 and m:
            if primes[k - 1] ** 2 > m and k == 1:
                return m - m // 2 if k == 1 else m
            k -= 1
            p = primes[k]
            m = phi(m, k) - phi(m // p, k)
        return m if m else 0

    def pi_partial(x):
        if x < 2:
            return 0
        r2 = int(x ** 0.5)
        while r2 * r2 > x:
            r2 -= 1
        while (r2 + 1) * (r2 + 1) <= x:
            r2 += 1
        if r2 < 2:
            return 0
        small = [0] * (r2 + 1)
        cnt = 0
        for i in range(2, r2 + 1):
            if small[i] == 0:
                cnt += 1
                for j in range(i, r2 + 1, i):
                    small[j] = 1
            small[i] = cnt
        large = [0] * (r2 + 1)
        for i in range(1, r2 + 1):
            large[i] = x // i - 1
        for p in range(2, r2 + 1):
            if small[p] == small[p - 1]:
                continue
            p2 = p * p
            sp = small[p - 1]
            for i in range(1, r2 // p + 1):
                large[i] -= large[i * p] - sp
            for i in range(r2 // p + 1, min(r2, p2 - 1) + 1):
                large[i] -= small[x // (i * p)] - sp
        return large[1]

    return pi_partial(x)


def solve(n):
    """Return the number of primes strictly less than n."""
    return _pi(n - 1) if n > 2 else 0


