def solve(n):
    """Return the count of primes strictly less than n.
    Uses Sieve of Eratosthenes with a bytearray for efficiency.
    """
    if n <= 2:
        return 0
    limit = n - 1
    # is_prime[i] == 1 means i is prime candidate
    is_prime = bytearray(b'\x01') * (limit + 1)
    # 0 and 1 are not prime
    if limit >= 0:
        is_prime[0] = 0
    if limit >= 1:
        is_prime[1] = 0
    import math
    for p in range(2, int(math.isqrt(limit)) + 1):
        if is_prime[p]:
            start = p * p
            step = p
            is_prime[start:limit+1:step] = b'\x00' * ((limit - start)//step + 1)
    return sum(is_prime)

