def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Uses patience sorting O(n log n) with bisect.
    """
    import bisect
    tail = []
    for x in nums:
        # find leftmost pile to replace
        i = bisect.bisect_left(tail, x)
        if i == len(tail):
            tail.append(x)
        else:
            tail[i] = x
    return len(tail)

