def solve(grid):
    """Count number of islands (connected components of 1s) in a grid.
    Cells are orthogonally adjacent (up, down, left, right). The grid may be empty
    or have rows of varying lengths.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    def neighbors(r, c):
        for dr, dc in ((1,0), (-1,0), (0,1), (0,-1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < len(grid[nr]):
                yield nr, nc
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            cr, cc = stack.pop()
            if (cr, cc) in visited:
                continue
            if grid[cr][cc] != 1:
                continue
            visited.add((cr, cc))
            for nr, nc in neighbors(cr, cc):
                if (nr, nc) not in visited and grid[nr][nc] == 1:
                    stack.append((nr, nc))
    count = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 1 and (i, j) not in visited:
                dfs(i, j)
                count += 1
    return count

